 ALTER TABLE "Assignment" ADD COLUMN "userName" TEXT, ADD COLUMN "userEmail" TEXT, ADD COLUMN "projectName" TEXT, ADD COLUMN "endDate" TIMESTAMP(3); UPDATE "Assignment" a SET "userName" = u."name", "userEmail" = u."email" FROM "User" u WHERE a."userId" = u."id"; UPDATE "Assignment" a SET "projectName" = p."name" FROM "Project" p WHERE a."projectId" = p."id"; UPDATE "Assignment" SET "userName" = COALESCE("userName", 'Unknown'), "userEmail" = COALESCE("userEmail", 'unknown@unknown'), "projectName" = COALESCE("projectName", 'Unknown') WHERE "userName" IS NULL OR "userEmail" IS NULL OR "projectName" IS NULL; ALTER TABLE "Assignment" ALTER COLUMN "userName" SET NOT NULL, ALTER COLUMN "userEmail" SET NOT NULL, ALTER COLUMN "projectName" SET NOT NULL;
